"""build_result_trackB_doc.py — renders the supplementary tables for docs/RESULT_trackB_dl_objective_2026-09-05.md from the ARCHIVED files only:
results/score_trackB.json (score level + DRO weights), results/leakcheck_*.json (leak gate), fits/*.json (trainer self-report per fold),
results/judge_trackB.json (identity receipt, ext-vs-0822 baseline difference). The book-level tables L/D/J come verbatim from results/trackB_tables.md
(written by judge_trackB.py on pod). usage: python3 build_result_trackB_doc.py <archive_dir> → <archive_dir>/trackB_supp_tables.md"""
import sys, os, json, glob
A = sys.argv[1] if len(sys.argv) > 1 else os.path.dirname(os.path.abspath(__file__))
out = []
def p(s=""): out.append(s); print(s)
J = json.load(open(f"{A}/results/judge_trackB.json")); SC = json.load(open(f"{A}/results/score_trackB.json"))
LK = {}
for f in sorted(glob.glob(f"{A}/results/leakcheck_*.json")):
    for k, v in json.load(open(f))["files"].items(): LK[k] = v
p(f"<!-- generated by build_result_trackB_doc.py from {os.path.basename(A)}/results/*.json and fits/*.json -->")
p("## S1 · Fit self-report per fold (VERIFIED fits/f10_V2MAIN_<arm>_s<seed>.json; training-frame numbers, not the book device): net bps/anchor on the fold's own test year, ES5, turnover, α*, best validation score, epochs; DRO last-epoch era weights (W_max / W_min / n_eff)")
p("| fit | seed | DRO_T | SS_W | self sha (patched trainer) | targets / fea82 / fea89 sha | fold | n_test | net bps | ES5 | turnover | α* | best_va | DRO eras / W_max / W_min / n_eff (last epoch) | argmax era by epoch |")
p("|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|")
for f in sorted(glob.glob(f"{A}/fits/f10_V2MAIN_*_s*.json")):
    R = json.load(open(f)); nm = os.path.basename(f)[len("f10_V2MAIN_"):-5]; L, S = nm.rsplit("_s", 1)
    for yv, fo in R["folds"].items():
        dro = SC["dro"].get(f"{L}_s{S}", {}).get("folds", {}).get(yv, {})
        dtxt = (f"{dro['n_eras']} / {dro['W_max']:.2f} / {dro['W_min']:.2f} / {dro['n_eff']:.2f}" if "n_eras" in dro else "-"); am = (str(dro.get("argmax_era_by_epoch", "-")) if "n_eras" in dro else "-")
        p(f"| {L} | {S} | {R.get('dro_t', '-')} | {R.get('ss_w', '-')} | {R['self_sha256'][:12]} | {R['targets_sha256'][:8]} / {R['fea82_sha256'][:8]} / {R['fea89_sha256'][:8]} | {yv} | {fo['n_test']} | {fo['net_mean_bps']:+.3f} | {fo['es5_bps']:.2f} | {fo['turnover_mean']:.4f} | {fo['alpha_final']:.4f} | {fo['best_va']:+.3f} | {dtxt} | {am} |")
p()
p("## S2 · Score level (VERIFIED results/score_trackB.json): per-anchor rank IC by year vs the same-seed ext baseline; side-conditional IC within the model's own bottom half (shorted names) / top half (longed names); paired ΔIC UTC-day-block bootstrap 2000 seed 20260905")
p("| fit | window | n | IC | ref IC | ΔIC [CI95] | short-half IC | ref | Δ [CI95] | long-half IC | ref | Δ [CI95] |")
p("|---|---|---|---|---|---|---|---|---|---|---|---|")
for k, lv in SC["levels"].items():
    d = SC["delta_vs_ext_baseline"][k]; fit, w = k.split("/")
    b = lambda q: f"{q['mean']:+.4f} [{q['lo']:+.4f},{q['hi']:+.4f}]"
    p(f"| {fit} | {w} | {lv['n']} | {lv['IC']:+.4f} | {lv['ref_IC']:+.4f} | {b(d['dIC'])} | {lv['IC_short_half']:+.4f} | {lv['ref_IC_short_half']:+.4f} | {b(d['dIC_short_half'])} | {lv['IC_long_half']:+.4f} | {lv['ref_IC_long_half']:+.4f} | {b(d['dIC_long_half'])} |")
p()
p("## S3 · Leak gate (VERIFIED results/leakcheck_*.json): spectrum mean Spearman(score_i, y4s_{i+k}), k ∈ [−3,+3], full test set stride 1; ① max|k>0| < |k0|; ③ finite cells before 2023-01-01 = 0; ② shape vs same-seed ext baseline (diagnostic)")
p("| fit | n test anchors | k−3 | k−2 | k−1 | **k0** | k+1 | k+2 | k+3 | ① future no peak | ③ pre-fold finite | ② max|Δ| vs ref | gate |")
p("|---|---|---|---|---|---|---|---|---|---|---|---|---|")
for k, v in LK.items():
    s = v["spectrum_own_full"]; g = lambda kk: s.get(str(kk), s.get(kk))
    p(f"| {k} | {v['n_test_anchors']} | " + " | ".join(f"{g(kk):+.4f}" for kk in (-3, -2, -1)) + f" | **{g(0):+.4f}** | " + " | ".join(f"{g(kk):+.4f}" for kk in (1, 2, 3)) + f" | {v['c1_future_no_peak_full']} (max {v['max_abs_future_full']:.4f}) | {v['c3_prefold_finite']} ({v['c3_pass']}) | {v['shape_vs_ref_maxabs']:.4f} | {'PASS' if v['leak_gate_pass_c1_and_c3'] else 'FAIL'} |")
p()
p("## S4 · Identity and baseline-lineage receipts (VERIFIED results/judge_trackB.json deltas)")
for name in ("IDENT_s42 − BASE_EXT_s42 [identity, exact 0 expected]", "BASE_EXT_s42 − BASE_s42 [ext data vs 0822 data, same trainer]", "BASE_EXT_s2027 − BASE_s2027 [ext vs 0822]"):
    d = J["deltas"].get(name)
    if not d: p(f"- {name}: n/a"); continue
    w = d["windows"]; p(f"- {name}: " + "; ".join(f"{k}: {w[k]['mean']:+.4f} [{w[k]['lo']:+.3f},{w[k]['hi']:+.3f}]" + (" (=0 exact)" if w[k]['exact_zero'] else f" max|Δ| {w[k]['maxabs']:.3g}") for k in ("pre-2023", "2023", "2024", "2025", "2026<=cut", "2024->26<=cut")) + f"; Δturn {d['dturn_pct_primary']:+.1f}%")
p()
p("## S5 · Structural cap (INFERRED arithmetic from VERIFIED levels): the DL leg enters the book as φ=0.45 of the model leg, which rides the msharpe seat w_king (mean below); a leg-level effect Δ_leg maps to at most ≈ φ × w_king × Δ_leg at book level")
for k, row in J["levels"].items():
    if k.startswith("BASE_EXT"): q = row["2024->26<=cut"]; p(f"- {k}: w_king (2024→26 mean) {q['w_king']:.3f} ⇒ φ·w_king = {0.45*q['w_king']:.3f}; gross {q['gross']:.3f}")
open(f"{A}/trackB_supp_tables.md", "w").write("\n".join(out) + "\n"); print(f"\nwrote {A}/trackB_supp_tables.md ({len(out)} lines)")
